#include <stdio.h>
#include <string.h>

int main(void) {
    char num[1005];
    char s[1005];
    int m;

    if (scanf("%s", num) != 1) return 0;
    scanf("%d", &m);

    int map[26];
    const char *groups[] = {
        "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"
    };

    for (int d = 2; d <= 9; d++) {
        const char *p = groups[d - 2];
        while (*p) {
            map[*p - 'a'] = d;
            p++;
        }
    }

    int len = strlen(num);
    int ans = 0;

    for (int i = 0; i < m; i++) {
        scanf("%s", s);

        if (strlen(s) != len) continue;

        int ok = 1;
        for (int j = 0; j < len; j++) {
            if (map[s[j] - 'a'] != num[j] - '0') {
                ok = 0;
                break;
            }
        }

        if (ok) ans++;
    }

    printf("%d\n", ans);

    return 0;
}
